mapper.select:
SELECT A.*,B.* FROM( SELECT tt1.rnum no, tt1.comment_id, tt1.member_id, tt1.content_id, tt1.collection_id, tt1.comment_detail, tt1.spoiler, TO_CHAR(tt1.created_dt,'YYYY/MM/DD HH24:MI:SS') created_dt, TO_CHAR(tt1.updated_dt,'YYYY/MM/DD HH24:MI:SS') updated_dt FROM( SELECT ROWNUM rnum, t1.* FROM ( SELECT * FROM user_comment
ORDER BY created_dt DESC, comment_id DESC )t1 WHERE ROWNUM <= ( #{pageSize} * (#{pageNo} -1 ) + #{pageSize} ) )tt1 WHERE rnum >= ( #{pageSize} * (#{pageNo} -1 ) + 1 ) ) A CROSS JOIN ( SELECT COUNT(*) total_cnt FROM user_comment
) B
